// SQD OKR Dashboard — renders data/okr-data.json (generated by scripts/parse_okr.py).

(() => {
  "use strict";

  const cssVar = (name) => getComputedStyle(document.documentElement).getPropertyValue(name).trim();

  function scoreClass(score) {
    if (score === null || score === undefined || typeof score !== "number") return "s-warning";
    if (score >= 3.5) return "s-good";
    if (score >= 2.5) return "s-warning";
    if (score >= 1.5) return "s-serious";
    return "s-critical";
  }

  function scoreBadge(score) {
    const label = typeof score === "number" ? (Math.round(score * 100) / 100) : (score ?? "—");
    return `<span class="badge-score ${scoreClass(score)}">${label}</span>`;
  }

  function fmtVal(v) {
    if (v === null || v === undefined || v === "") return "—";
    return v;
  }

  function legendHtml(items) {
    return items.map((it) => `<li><span class="swatch" style="background:${it.color}"></span>${it.label}</li>`).join("");
  }

  function chipHtml(label, value, color) {
    return `<span class="chip"><span class="chip-swatch" style="background:${color}"></span>${label} <span class="chip-value">${fmtVal(value)}</span></span>`;
  }

  function notesRows(months, tbody) {
    tbody.innerHTML = months.map((m) => `
      <tr>
        <td>${m.month}</td>
        <td>${scoreBadge(m.score)}</td>
        <td class="note-text">${fmtVal(m.text)}</td>
      </tr>
    `).join("");
  }

  function targetLine(planText, stretchText) {
    let out = "";
    if (planText) out += `Target: ${planText}`;
    if (stretchText) out += (out ? " · " : "") + `Stretch: ${stretchText}`;
    return out;
  }

  // ---------- Tabs ----------
  const tabs = document.querySelectorAll(".tab-btn");
  tabs.forEach((btn) => {
    btn.addEventListener("click", () => {
      tabs.forEach((b) => b.classList.remove("active"));
      document.querySelectorAll(".tab-panel").forEach((p) => p.classList.remove("active"));
      btn.classList.add("active");
      document.getElementById(`panel-${btn.dataset.tab}`).classList.add("active");
      // Charts drawn on hidden panels get zero-width canvases; redraw once visible.
      if (window.__okrRedraw) window.__okrRedraw();
    });
  });

  // ---------- Theme ----------
  const themeToggle = document.getElementById("theme-toggle");
  function applyStoredTheme() {
    let stored = null;
    try { stored = localStorage.getItem("sqd-theme"); } catch (e) { /* ignore */ }
    if (stored) document.documentElement.setAttribute("data-theme", stored);
  }
  themeToggle.addEventListener("click", () => {
    const current = document.documentElement.getAttribute("data-theme");
    const next = current === "dark" ? "light" : "dark";
    document.documentElement.setAttribute("data-theme", next);
    try { localStorage.setItem("sqd-theme", next); } catch (e) { /* ignore */ }
    if (window.__okrRedraw) window.__okrRedraw();
  });
  applyStoredTheme();

  // ---------- Load data & render ----------
  fetch("data/okr-data.json")
    .then((r) => r.json())
    .then((data) => {
      const redraws = [];
      render(data, redraws);
      window.__okrRedraw = () => redraws.forEach((fn) => fn());
      window.addEventListener("resize", () => window.__okrRedraw());
    })
    .catch((err) => {
      document.querySelector(".app").insertAdjacentHTML(
        "afterbegin",
        `<div class="panel" style="border-color:var(--status-critical)"><strong>Could not load data/okr-data.json.</strong> If you're opening this file directly (file://), serve it over a local web server instead (e.g. <code>python3 -m http.server</code>) — fetch() of local JSON is blocked otherwise.<br><small>${err}</small></div>`
      );
    });

  function render(data, redraws) {
    document.getElementById("page-subtitle").textContent =
      `Monthly progress of Objectives & Key Results, ${data.year}. Generated ${new Date(data.generatedAt).toLocaleString()}.`;

    const months = data.months;
    const krById = {};
    data.objectives.forEach((o) => o.krs.forEach((kr) => (krById[kr.id] = kr)));

    // ---- Overview ----
    const overallVals = data.overallScoreTrend.map((m) => (typeof m.score === "number" ? m.score : null));
    const chartOverall = document.getElementById("chart-overall");
    document.getElementById("legend-overall").innerHTML = legendHtml([{ label: "Weighted score (scale 1-4)", color: cssVar("--cat-1") }]);
    redraws.push(() => Charts.drawLineChart(chartOverall, [{ label: "Score", color: cssVar("--cat-1"), values: overallVals }], {
      categories: months, yMin: 1, yMax: 4, yStep: 1,
    }));

    const objColors = ["--cat-1", "--cat-2", "--cat-3", "--cat-4", "--cat-7"];
    const objListEl = document.getElementById("obj-weight-list");
    objListEl.innerHTML = data.objectives.map((o, i) => {
      const w = typeof o.weight === "number" ? o.weight : 0;
      const pct = Math.round(w * 100);
      return `
        <div class="obj-row">
          <span class="obj-name">Obj ${o.id} — ${o.name}</span>
          <div class="obj-track"><div class="obj-fill" style="width:${pct}%;background:${cssVar(objColors[i % objColors.length])}"></div></div>
          <span class="obj-weight">${pct}%</span>
        </div>`;
    }).join("");

    const objCardsEl = document.getElementById("obj-cards");
    objCardsEl.innerHTML = data.objectives.map((o) => {
      const scores = o.krs.map((k) => k.ytd.score).filter((s) => typeof s === "number");
      const avg = scores.length ? scores.reduce((a, b) => a + b, 0) / scores.length : null;
      return `
        <div class="obj-card">
          <div class="obj-card-title">Obj ${o.id} — ${o.name}</div>
          <div class="obj-card-weight">${o.krs.length} KR${o.krs.length > 1 ? "s" : ""} · weight ${typeof o.weight === "number" ? Math.round(o.weight * 100) + "%" : "—"}</div>
          <div class="obj-card-foot"><span>YTD avg score</span>${scoreBadge(avg === null ? null : Math.round(avg * 100) / 100)}</div>
        </div>`;
    }).join("");

    // ---- 1. Supplier complaints ----
    const kr2 = data.parsed.supplierComplaints.kr2;
    const kr5 = data.parsed.supplierComplaints.kr5;
    document.getElementById("kr2-target").textContent = targetLine(kr2.planText, null);
    const chartKr2 = document.getElementById("chart-kr2");
    redraws.push(() => Charts.drawBarChart(chartKr2,
      [{ label: "DMN actual", color: cssVar("--cat-1"), values: kr2.months.map((m) => m.actual) }],
      { categories: months, refLine: undefined }));
    document.getElementById("kr2-ytd").innerHTML =
      chipHtml("YTD actual", kr2.ytd.actual, cssVar("--cat-1")) +
      chipHtml("YTD target", kr2.ytd.target, cssVar("--text-muted"));

    document.getElementById("kr5-target").textContent = targetLine(kr5.planText, null);
    notesRows(kr5.months, document.querySelector("#kr5-notes tbody"));

    // ---- 2. Audits ----
    const audits = data.parsed.audits;
    document.getElementById("audit-target").textContent = targetLine(audits.planText, audits.stretchText);
    const auditSeriesDef = [
      { key: "vda", label: "VDA 6.3", color: cssVar("--cat-1") },
      { key: "cqi", label: "CQI", color: cssVar("--cat-2") },
      { key: "pcpa", label: "PCPA", color: cssVar("--cat-3") },
      { key: "psa", label: "PSA", color: cssVar("--cat-4") },
      { key: "other", label: "Customer specific / other", color: cssVar("--cat-7") },
    ];
    document.getElementById("legend-audits").innerHTML = legendHtml(auditSeriesDef);
    const chartAudits = document.getElementById("chart-audits");
    redraws.push(() => Charts.drawBarChart(chartAudits,
      auditSeriesDef.map((s) => ({ label: s.label, color: s.color, values: audits.months.map((m) => m[s.key] || 0) })),
      { categories: months, stacked: true }));
    document.getElementById("audit-ytd").innerHTML = auditSeriesDef.map((s) =>
      `<div class="mini-stat"><div class="ms-label"><span class="ms-swatch" style="background:${s.color}"></span>${s.label}</div><div class="ms-value">${fmtVal(audits.ytd[s.key])}</div><div class="ms-sub">YTD total audits</div></div>`
    ).join("");
    notesRows(audits.months, document.querySelector("#audit-notes tbody"));

    // ---- 3. APQP status ----
    const kr7 = data.parsed.apqp.kr7_kickoffRunRate;
    const kr8 = data.parsed.apqp.kr8_ppapOts;
    const kr9 = data.parsed.apqp.kr9_ppapFtq;
    document.getElementById("kr7-target").textContent = targetLine(kr7.planText, null);
    const legendKr7 = [{ label: "New Sourcing / Kick-off", color: cssVar("--cat-7") }, { label: "Run @ Rate", color: cssVar("--cat-1") }];
    document.getElementById("legend-kr7").innerHTML = legendHtml(legendKr7);
    const chartKr7 = document.getElementById("chart-kr7");
    redraws.push(() => Charts.drawBarChart(chartKr7,
      [
        { label: "New Sourcing / Kick-off", color: cssVar("--cat-7"), values: kr7.months.map((m) => m.newSourcing) },
        { label: "Run @ Rate", color: cssVar("--cat-1"), values: kr7.months.map((m) => m.runRate) },
      ], { categories: months }));

    document.getElementById("kr8-target").textContent = targetLine(kr8.planText, null);
    const legendKr8 = [{ label: "PPAP", color: cssVar("--cat-1") }, { label: "OTS", color: cssVar("--cat-2") }];
    document.getElementById("legend-kr8").innerHTML = legendHtml(legendKr8);
    const chartKr8 = document.getElementById("chart-kr8");
    redraws.push(() => Charts.drawBarChart(chartKr8,
      [
        { label: "PPAP", color: cssVar("--cat-1"), values: kr8.months.map((m) => m.ppap) },
        { label: "OTS", color: cssVar("--cat-2"), values: kr8.months.map((m) => m.ots) },
      ], { categories: months }));

    document.getElementById("kr9-target").textContent = targetLine(kr9.planText, null);
    const chartKr9 = document.getElementById("chart-kr9");
    redraws.push(() => Charts.drawBarChart(chartKr9,
      [{ label: "PPAP approved", color: cssVar("--cat-3"), values: kr9.months.map((m) => m.ppapApproved) }],
      { categories: months }));

    document.getElementById("sop-note").textContent = data.parsed.apqp.sopNote;

    // ---- 4. Safe launch ----
    const kr10 = data.parsed.safeLaunch.kr10;
    document.getElementById("kr10-target").textContent = targetLine(kr10.planText, kr10.stretchText);
    const legendSL = [{ label: "Safe launch pass", color: cssVar("--status-good") }, { label: "Safe launch fail", color: cssVar("--status-critical") }, { label: "Run @ Rate", color: cssVar("--cat-1") }];
    document.getElementById("legend-safelaunch").innerHTML = legendHtml(legendSL);
    const chartSL = document.getElementById("chart-safelaunch");
    redraws.push(() => Charts.drawBarChart(chartSL,
      [
        { label: "Pass", color: cssVar("--status-good"), values: kr10.months.map((m) => m.safeLaunchPass) },
        { label: "Fail", color: cssVar("--status-critical"), values: kr10.months.map((m) => m.safeLaunchFail) },
        { label: "Run @ Rate", color: cssVar("--cat-1"), values: kr10.months.map((m) => m.runRate) },
      ], { categories: months }));
    document.getElementById("safelaunch-ytd").innerHTML =
      `<div class="mini-stat"><div class="ms-label"><span class="ms-swatch" style="background:${cssVar("--status-good")}"></span>Pass</div><div class="ms-value">${fmtVal(kr10.ytd.safeLaunchPass)}</div><div class="ms-sub">YTD parts</div></div>` +
      `<div class="mini-stat"><div class="ms-label"><span class="ms-swatch" style="background:${cssVar("--status-critical")}"></span>Fail</div><div class="ms-value">${fmtVal(kr10.ytd.safeLaunchFail)}</div><div class="ms-sub">YTD parts</div></div>` +
      `<div class="mini-stat"><div class="ms-label"><span class="ms-swatch" style="background:${cssVar("--cat-1")}"></span>Run @ Rate</div><div class="ms-value">${fmtVal(kr10.ytd.runRate)}</div><div class="ms-sub">YTD count</div></div>`;
    notesRows(kr10.months, document.querySelector("#safelaunch-notes tbody"));

    // ---- 5. EOS ----
    const kr13 = data.parsed.eos.kr13;
    document.getElementById("eos-target").textContent = targetLine(kr13.planText, kr13.stretchText);
    const latestEos = [...kr13.months].reverse().find((m) => typeof m.value === "number");
    document.getElementById("eos-hero").textContent = latestEos ? latestEos.value : "—";
    const chartEos = document.getElementById("chart-eos");
    redraws.push(() => Charts.drawLineChart(chartEos,
      [{ label: "EOS score", color: cssVar("--cat-1"), values: kr13.months.map((m) => (typeof m.value === "number" ? m.value : null)) }],
      { categories: months, yMin: 0, yMax: 10, yStep: 2, refLine: 9 }));

    // ---- 6. AI Assistant ----
    const kr14 = data.parsed.aiAssistant.kr14;
    document.getElementById("ai-target").textContent = targetLine(kr14.planText, kr14.stretchText);
    const chartAi = document.getElementById("chart-ai");
    redraws.push(() => Charts.drawBarChart(chartAi,
      [{ label: "Tasks completed", color: cssVar("--cat-7"), values: kr14.months.map((m) => m.count) }],
      { categories: months, yMax: 14, refLine: 6 }));
    document.getElementById("ai-note").textContent =
      "Reference line at 6 = base target (1 task/person × 6). Stretch target is 12 (2 tasks/person × 6). " + (kr14.ytd.text || "");

    window.__okrRedraw = () => redraws.forEach((fn) => fn());
    window.__okrRedraw();
  }
})();
